<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_admin();$monthly=db()->query('SELECT DATE_FORMAT(transaction_date,"%Y-%m-01") month_start,SUM(CASE WHEN type="income" THEN amount ELSE 0 END) income,SUM(CASE WHEN type="expense" THEN amount ELSE 0 END) expense FROM transactions WHERE status="active" GROUP BY month_start ORDER BY month_start DESC LIMIT 6')->fetchAll();$top=db()->query('SELECT c.name,SUM(t.amount) amount,COUNT(*) records FROM transactions t JOIN categories c ON c.category_id=t.category_id WHERE t.status="active" AND t.type="expense" GROUP BY c.category_id,c.name ORDER BY amount DESC LIMIT 8')->fetchAll();$pageTitle='Analytics';$activePage='analytics';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">SYSTEM INTELLIGENCE</span><h1>Usage analytics</h1><p>Review adoption and transaction activity.</p></div></section><div class="stats-grid"><div class="stat-card"><span>Six-month income</span><strong><?=money(array_sum(array_map(fn($r)=>(float)$r['income'],$monthly)))?></strong></div><div class="stat-card"><span>Six-month expense</span><strong><?=money(array_sum(array_map(fn($r)=>(float)$r['expense'],$monthly)))?></strong></div><div class="stat-card"><span>Months tracked</span><strong><?=count($monthly)?></strong></div><div class="stat-card"><span>Top categories</span><strong><?=count($top)?></strong></div></div><div class="two-column"><section class="panel"><div class="panel-head"><div><span class="panel-kicker">TREND</span><h2>Income vs expense</h2></div></div><div class="chart-box"><canvas id="adminChart"></canvas></div></section><section class="panel"><div class="panel-head"><div><span class="panel-kicker">EXPENSE USAGE</span><h2>Top categories</h2></div></div><?php foreach($top as$r):?><div class="rank-row"><span><?=e($r['name'])?></span><b><?=money($r['amount'])?></b></div><?php endforeach;?></section></div><script>window.ADMIN_DATA=<?=json_encode(['labels'=>array_map(fn($r)=>date('M Y',strtotime($r['month_start'])),$monthly),'income'=>array_map(fn($r)=>(float)$r['income'],$monthly),'expense'=>array_map(fn($r)=>(float)$r['expense'],$monthly)],JSON_UNESCAPED_UNICODE)?>;</script><?php require __DIR__.'/../includes/footer.php';?>